#!/usr/bin/env bash
# Sourced by the isolated driver after Cinnamon completes native allocation.
content_result=$(eval_cinnamon 'String((function(){var a=Main.AppletManager.getRunningInstancesForUuid("z-usage@oss-singularity")[0],p=a.menu.actor.get_transformed_position(),s=a.menu.actor.get_transformed_size(),bad=[],checked=0;function visit(actor){if(!actor.visible || !actor.mapped)return;var children=actor.get_children();if(actor.get_vscroll_bar){if(typeof actor.vscrollbar_visible!=="boolean" || typeof actor.hscrollbar_visible!=="boolean")throw new Error("Scrollbar visibility unavailable");children=children.filter(function(c){return (c!==actor.get_vscroll_bar() || actor.vscrollbar_visible) && (c!==actor.get_hscroll_bar() || actor.hscrollbar_visible);});}if(!children.length){checked++;var q=actor.get_transformed_position(),t=actor.get_transformed_size();if(actor.has_style_class_name && actor.has_style_class_name("popup-separator-menu-item"))return;if(actor.get_layout){var ink=actor.get_layout().get_pixel_extents()[0];q[0]+=ink.x;t[0]=ink.width;}if(t[0]>0 && t[1]>0 && (Math.round(q[0])<Math.round(p[0])-1 || Math.round(q[0]+t[0])>Math.round(p[0]+s[0])+1))bad.push({type:actor.toString(),x:q[0],width:t[0]});}children.forEach(visit);}visit(a.menu.actor);return bad.length?JSON.stringify({bad:bad,geometry:[a.menu.actor,a.menu.box,a.menu._scroll,a.menu._content.actor].map(function(n){return {position:n.get_transformed_position(),size:n.get_transformed_size(),preferred:n.get_preferred_width(-1),padding:n.get_theme_node().get_horizontal_padding()};})}):checked>10?true:"Insufficient mapped content to verify";})())')
if ! grep -qE "['\"]true['\"]" <<< "$content_result"; then
    printf 'Popup content extends beyond its visible width: %s\n' "$content_result" >&2
    exit 1
fi
printf 'Popup content: visible rings, labels and charts stay inside horizontal bounds\n'
